/* ServerNet homepage: infrastructure first, consumer Studio second. */
.sn-hero-carousel{position:relative;isolation:isolate;overflow:hidden;--hero-duration:6000ms;--studio-ink:var(--sn-ink,#edf5ff);--studio-copy:var(--sn-copy,#a9b6ca);--studio-edge:rgba(111,188,233,.19)}
.sn-hero-slides{display:grid;position:relative}
.sn-hero-slides>[data-hero-slide]{grid-area:1/1;min-width:0;align-self:stretch;transition:opacity .75s cubic-bezier(.22,1,.36,1),transform .95s cubic-bezier(.22,1,.36,1),filter .7s,visibility 0s .8s}
.sn-hero-slides>[data-hero-slide="studio"]{opacity:0;visibility:hidden;pointer-events:none;transform:translate3d(2%,0,0) scale(.985);filter:blur(9px)}
.sn-hero-carousel[data-carousel-ready] [data-hero-slide]{opacity:0;visibility:hidden;pointer-events:none;transform:translate3d(-2%,0,0) scale(.985);filter:blur(9px)}
.sn-hero-carousel[data-carousel-ready] [data-hero-slide].is-active{opacity:1;visibility:visible;pointer-events:auto;transform:none;filter:none;transition-delay:0s}
html[dir="rtl"] .sn-hero-carousel[data-carousel-ready] [data-hero-slide]:not(.is-active){transform:translate3d(2%,0,0) scale(.985)}
.sn-hero-carousel::after{content:"";position:absolute;inset:0;z-index:5;pointer-events:none;opacity:0;background:linear-gradient(108deg,transparent 28%,rgba(101,196,240,.025) 42%,rgba(149,226,255,.14) 49%,rgba(42,177,226,.035) 56%,transparent 70%);transform:translateX(-110%) skewX(-12deg)}
.sn-hero-carousel.is-transitioning::after{animation:sn-hero-glass-wipe 1.05s cubic-bezier(.25,.6,.2,1) both}
.sn-hero-controls{display:none;position:relative;z-index:6;align-items:center;gap:22px;min-height:68px;padding-block:10px 18px!important}
[data-carousel-ready] .sn-hero-controls{display:flex}

